Lemma sgrow_trans : forall c1 b1 a1 c2 b2 a2 A B C h1 h2 h3,
  sgrow c1 b1 a1 A B h1 h2 -> sgrow c2 b2 a2 B C h2 h3 -> sgrow (c1 + c2) (b1 + b2) (a1 + a2) A C h1 h3.
Proof.
