Lemma sgrow_am : forall A A' h h' pg, am_grow h h' ->
  ((0 < spare A /\ h' = h /\ a_areas A' = a_areas A /\ spare A' = spare A - 1)
   \/ (spare A = 0 /\ a_areas A' = a_areas A ++ [pg] /\ a_ctx A' KAmc = 100 /\ a_freelist A' = [])) ->
  sgrow 1 8192 1 A A' h h'.
